229	
230	    /**
231	     * Resolves the name of the currently authenticated user for audit logging, falling back to
232	     * {@code "anonymous"} when there is no authentication in the security context.
233	     *
234	     * @return the authenticated user name, never {@code null}
235	     */
236	    private static String currentUsername() {
237	        Authentication authentication = SecurityContextHolder.getContext().getAuthentication();
238	        return authentication == null ? "anonymous" : authentication.getName();
239	    }
240	
241	    /**
242	     * The number of owners at the head of the registration sequence that receive the
243	     * {@code 'FOUNDING'} membership tier. The first {@value #MAX_FOUNDING_OWNERS} owners ever
244	     * created are {@code 'FOUNDING'}; all later owners are {@code 'STANDARD'}.
245	     */
246	    private static final int MAX_FOUNDING_OWNERS = 100;
247	
248	    /**
249	     * The maximum number of owners that may be registered on any single calendar day.
250	     */
251	    private static final long MAX_DAILY_REGISTRATIONS = 20;
252	
253	    /**
254	     * Determines whether the daily owner-registration limit has already been reached. Owners are
255	     * counted by their {@link Owner#getRegistrationDate() registration date}, so once
256	     * {@value #MAX_DAILY_REGISTRATIONS} owners have been registered with today's date, no further
257	     * owners may be created today.
258	     *
259	     * @return {@code true} if today's registration limit has been reached
260	     */
261	    private boolean hasReachedDailyRegistrationLimit() {
262	        LocalDate today = LocalDate.now();
263	        long registeredToday = this.clinicService.findAllOwners().stream()
264	            .filter(existing -> today.equals(existing.getRegistrationDate()))
265	            .count();
266	        return registeredToday >= MAX_DAILY_REGISTRATIONS;
267	    }
268	
269	    /**
270	     * The maximum number of owners that may be registered in any single city.
271	     */
272	    private static final long MAX_OWNERS_PER_CITY = 8;
273	
274	    /**
275	     * Determines whether the given city has already reached its owner limit. Owners are matched to
276	     * the city using {@link #normalize(String)}, so the count ignores letter case and any
277	     * surrounding or repeated whitespace. Once {@value #MAX_OWNERS_PER_CITY} owners live in a city,
278	     * no further owners may be created there.
279	     *
280	     * @param city the city of the new owner, may be {@code null}
281	     * @return {@code true} if the city already contains {@value #MAX_OWNERS_PER_CITY} owners
282	     */
283	    private boolean hasReachedCityOwnerLimit(String city) {
284	        String normalized = normalize(city);
285	        long ownersInCity = this.clinicService.findAllOwners().stream()
286	            .filter(existing -> Objects.equals(normalize(existing.getCity()), normalized))
287	            .count();
288	        return ownersInCity >= MAX_OWNERS_PER_CITY;
289	    }
290	
291	    /**
292	     * Builds the customer code for a newly created owner, formatted as
293	     * {@code '<UPPERCASE_CITY>-<NNNN>'} where {@code NNNN} is one more than the number of owners
294	     * already registered in that city, zero-padded to four digits (e.g. {@code 'LONDON-0007'}).
295	     *
296	     * @param city the city of the new owner
297	     * @return the assigned customer code
298	     */
299	    private String nextCustomerCode(String city) {
300	        long ownersInCity = this.clinicService.findAllOwners().stream()
301	            .filter(existing -> Objects.equals(
302	                normalize(existing.getCity()), normalize(city)))
303	            .count();
304	        return String.format("%s-%04d", city.toUpperCase(Locale.ROOT), ownersInCity + 1);
305	    }
306	
307	    /**
308	     * Resolves the city to store for a newly created owner. The city is title-cased (so
309	     * {@code "new york"} becomes {@code "New York"}), unless an owner already lives in that
310	     * city, in which case the existing owner's exact spelling of the city name is reused. Cities
311	     * are matched using {@link #normalize(String)}, so the match ignores letter case and any
312	     * surrounding or repeated whitespace.
313	     *
314	     * @param city the city supplied for the new owner, may be {@code null}
315	     * @return the city to store, or {@code null} if the input was {@code null}
316	     */
317	    private String resolveCity(String city) {
318	        if (city == null) {
319	            return null;
320	        }
321	        String normalized = normalize(city);
322	        if (!normalized.isEmpty()) {
323	            for (Owner existing : this.clinicService.findAllOwners()) {
324	                if (normalized.equals(normalize(existing.getCity()))) {
325	                    return existing.getCity();
326	                }
327	            }
328	        }
329	        return toTitleCase(city);
330	    }
331	
332	    /**
333	     * Title-cases free-form text by upper-casing the first letter of each whitespace-separated word
334	     * and lower-casing the remaining letters, preserving the original whitespace. For example
335	     * {@code "new  YORK"} becomes {@code "New  York"}.
336	     *
337	     * @param value the raw value, never {@code null}
338	     * @return the title-cased value
339	     */
340	    private static String toTitleCase(String value) {
341	        StringBuilder result = new StringBuilder(value.length());
342	        boolean startOfWord = true;
343	        for (int i = 0; i < value.length(); i++) {
344	            char c = value.charAt(i);
345	            if (Character.isWhitespace(c)) {
346	                startOfWord = true;
347	                result.append(c);
348	            } else if (startOfWord) {
349	                result.append(Character.toTitleCase(c));
350	                startOfWord = false;
351	            } else {
352	                result.append(Character.toLowerCase(c));
353	            }
354	        }
355	        return result.toString();
356	    }
357	
358	    /**
359	     * Resolves the locality of a newly created owner relative to the owners present at the moment
360	     * it is created. The value is {@code "local"} when the new owner's city is the single most
361	     * common city among the existing owners, and {@code "remote"} otherwise. Cities are matched
362	     * using {@link #normalize(String)}, so the comparison ignores letter case and any surrounding
363	     * or repeated whitespace. When there are no existing owners, or when two or more cities tie for
364	     * the highest owner count, no city is the sole most common one and the result is
365	     * {@code "remote"}.
366	     *
367	     * @param city the city supplied for the new owner, may be {@code null}
368	     * @return {@code "local"} if the city is the single most common city, otherwise {@code "remote"}
369	     */
370	    private String resolveLocality(String city) {
371	        String normalized = normalize(city);
372	        Map<String, Long> ownersPerCity = this.clinicService.findAllOwners().stream()
373	            .map(existing -> normalize(existing.getCity()))
374	            .filter(normalizedCity -> !normalizedCity.isEmpty())
375	            .collect(Collectors.groupingBy(normalizedCity -> normalizedCity, Collectors.counting()));
376	        long highestCount = ownersPerCity.values().stream()
377	            .mapToLong(Long::longValue)
378	            .max()
379	            .orElse(0L);
380	        if (highestCount == 0L) {
381	            return "remote";
382	        }
383	        List<String> mostCommonCities = ownersPerCity.entrySet().stream()
384	            .filter(entry -> entry.getValue() == highestCount)
385	            .map(Map.Entry::getKey)
386	            .toList();
387	        boolean isSingleMostCommon = mostCommonCities.size() == 1
388	            && mostCommonCities.get(0).equals(normalized);
389	        return isSingleMostCommon ? "local" : "remote";
390	    }
391	
392	    /**
393	     * Counts how many existing owners share the given last name. Last names are matched using
394	     * {@link #normalize(String)}, so the count ignores letter case and any surrounding or repeated
395	     * whitespace. This is evaluated against the owners present at the moment the new owner is
396	     * created, before the new owner is persisted, so the new owner does not count itself.
397	     *
398	     * @param lastName the last name of the new owner, may be {@code null}
399	     * @return the number of existing owners sharing the same last name
400	     */
401	    private int countNamesakes(String lastName) {
402	        String normalized = normalize(lastName);
403	        return (int) this.clinicService.findAllOwners().stream()
404	            .filter(existing -> normalized.equals(normalize(existing.getLastName())))
405	            .count();
406	    }
407	
408	    /**
409	     * Determines whether the new owner shares a household with an existing owner, meaning another
410	     * owner already has the same address and city. Both the address and the city are matched using
411	     * {@link #normalize(String)}, so the comparison ignores letter case and any surrounding or
412	     * repeated whitespace. This is evaluated against the owners present at the moment the new owner
413	     * is created, before the new owner is persisted, so the new owner does not count itself.
414	     *
415	     * @param address the address of the new owner, may be {@code null}
416	     * @param city    the city of the new owner, may be {@code null}
417	     * @return {@code true} if an existing owner already has the same address and city
418	     */
419	    private boolean sharesHousehold(String address, String city) {
420	        String normalizedAddress = normalize(address);
421	        String normalizedCity = normalize(city);
422	        return this.clinicService.findAllOwners().stream()
423	            .anyMatch(existing -> normalizedAddress.equals(normalize(existing.getAddress()))
424	                && normalizedCity.equals(normalize(existing.getCity())));
425	    }
426	
427	    /**
428	     * Determines whether the given telephone number is already used by any other owner.
429	     *
430	     * @param owner the candidate owner
431	     * @return {@code true} if an owner with the same telephone number already exists in the data store
432	     */
433	    private boolean isDuplicateOwner(Owner owner) {
434	        return this.clinicService.findAllOwners().stream()
435	            .anyMatch(existing -> Objects.equals(existing.getTelephone(), owner.getTelephone()));
436	    }
437	
438	    /**
439	     * Determines whether the given email address is already used by any other owner. An owner
440	     * without an email address is never considered a duplicate on this criterion. Email addresses
441	     * are compared using {@link #normalize(String)} so the check ignores letter case and any
442	     * surrounding or repeated whitespace.
443	     *
444	     * @param owner the candidate owner
445	     * @return {@code true} if the owner provides an email already used by an existing owner
446	     */
447	    private boolean isDuplicateEmail(Owner owner) {
448	        String email = normalize(owner.getEmail());
449	        if (email.isEmpty()) {
450	            return false;
451	        }
452	        return this.clinicService.findAllOwners().stream()
453	            .anyMatch(existing -> email.equals(normalize(existing.getEmail())));
454	    }
455	
456	    /**
457	     * The minimum number of existing owners that must share a new owner's area code before the
458	     * creation is flagged as a possible bulk signup. When {@value #MIN_AREA_CODE_BULK_SIGNUP} or
459	     * more existing owners already share the area code, a WARN is emitted to the audit log.
460	     */
461	    private static final int MIN_AREA_CODE_BULK_SIGNUP = 5;
462	
463	    /**
464	     * Extracts the area code (the first three digits) from an already
465	     * {@link #normalizeTelephone(String) normalized} telephone number. A telephone that is
466	     * {@code null} or has fewer than three digits has no area code.
467	     *
468	     * @param telephone the digits-only telephone number, may be {@code null}
469	     * @return the three-digit area code, or {@code null} if none can be determined
470	     */
471	    private static String areaCode(String telephone) {
472	        if (telephone == null || telephone.length() < 3) {
473	            return null;
474	        }
475	        return telephone.substring(0, 3);
476	    }
477	
478	    /**
479	     * Counts how many existing owners share the given telephone's area code (its first three
480	     * digits). This is evaluated against the owners present at the moment the new owner is created,
481	     * before the new owner is persisted, so the new owner does not count itself. Owners whose
482	     * telephone has no determinable area code are ignored, and a candidate telephone without an area
483	     * code matches no one.
484	     *
485	     * @param telephone the normalized telephone number of the new owner, may be {@code null}
486	     * @return the number of existing owners sharing the same area code
487	     */
488	    private long countOwnersSharingAreaCode(String telephone) {
489	        String areaCode = areaCode(telephone);
490	        if (areaCode == null) {
491	            return 0L;
492	        }
493	        return this.clinicService.findAllOwners().stream()
494	            .filter(existing -> areaCode.equals(areaCode(normalizeTelephone(existing.getTelephone()))))
495	            .count();
496	    }
497	
498	    /**
499	     * Normalizes a telephone number to digits only by stripping spaces, dashes and parentheses, so
500	     * that a value such as {@code "(613) 555-0100"} is stored and compared as {@code "6135550100"}.
501	     * This is applied before an owner is stored and before the telephone-uniqueness check, so two
502	     * differently formatted representations of the same number are treated as duplicates. A
503	     * {@code null} value is returned unchanged.
504	     *
505	     * @param telephone the raw telephone number, may be {@code null}
506	     * @return the digits-only telephone number, or {@code null} if the input was {@code null}
507	     */
508	    private static String normalizeTelephone(String telephone) {
509	        if (telephone == null) {
510	            return null;
511	        }
512	        return telephone.replaceAll("[\\s()-]", "");
513	    }
514	
515	    /**
516	     * Normalizes free-form text for duplicate detection so that comparisons ignore letter case and
517	     * surrounding or repeated whitespace: the value is trimmed, runs of internal whitespace are
518	     * collapsed to a single space and the result is lower-cased. This is what makes
519	     * {@code "  john   smith "} and {@code "John Smith"} count as the same value when detecting
520	     * duplicates. A {@code null} value normalizes to the empty string.
521	     *
522	     * @param value the raw value, may be {@code null}
523	     * @return the normalized value, never {@code null}
524	     */
525	    private static String normalize(String value) {
526	        if (value == null) {
527	            return "";
528	        }
529	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
530	    }
531	
532	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
533	    @Override
534	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
535	        Owner owner = this.clinicService.findOwnerById(ownerId);
536	        if (owner != null) {
537	            Pet pet = owner.getPet(petId);
538	            if (pet != null) {
539	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
540	            }
541	        }
542	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
543	    }
544	}
